static void temporaries_pop(struct em_temporaries *members)
{
	struct neocc_temporary *top = members->top;

	members->top = top->prev;
	neocc_string_clear(&top->string);
	free(top);
}

static void temporaries_clear(struct em_temporaries *members)
{
	while (members->top)
		temporaries_pop(members);
}

static int temporaries_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	if (self->ref_count == 1)
		temporaries_clear(self->members);
	return R_P;
}

static int temporaries_close(struct object *self,
	const struct vr *caller_context)
{
	struct em_temporaries *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		temporaries_clear(members);
	return R_P;
}

static int temporaries_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_temporaries *members = self->members;
	struct neocc_temporary *boundary;

	if (action != NEOCC_AC0_TEMPORARIES_RESET &&
	    action != NEOCC_AC0_TEMPORARIES_ENTER &&
	    action != NEOCC_AC0_TEMPORARIES_UNWIND &&
	    action != NEOCC_AC0_TEMPORARIES_LEAVE) {
		SBO_OBJECT_INTERACT0;
	}
	if (!self->ref_count)
		return RN_INVALIDARG;
	if (action == NEOCC_AC0_TEMPORARIES_RESET) {
		temporaries_clear(members);
		return R_P;
	}
	if (action == NEOCC_AC0_TEMPORARIES_ENTER) {
		boundary = malloc(sizeof(*boundary));
		if (!boundary)
			return R_N;
		*boundary = (struct neocc_temporary){
			.prev = members->top, .boundary = 1 };
		members->top = boundary;
		return R_P;
	}
	for (boundary = members->top; boundary && !boundary->boundary;
	     boundary = boundary->prev)
		;
	if (!boundary)
		return action == NEOCC_AC0_TEMPORARIES_UNWIND ?
			R_P : RN_INVALIDARG;
	while (members->top != boundary)
		temporaries_pop(members);
	if (action == NEOCC_AC0_TEMPORARIES_LEAVE)
		temporaries_pop(members);
	return R_P;
}

