static int temporaries_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_temporaries *members = self->members;
	struct neocc_temporary *entry;
	struct neocc_string *string;

	*output_quantity = 0;
	if (action != NEOCC_AC1_TEMPORARIES_PUSH) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || capacity < sizeof(string))
		return RN_INVALIDARG;
	entry = malloc(sizeof(*entry));
	if (!entry)
		return R_N;
	*entry = (struct neocc_temporary){ .prev = members->top };
	members->top = entry;
	string = &entry->string;
	memcpy(output_stream, &string, sizeof(string));
	*output_quantity = sizeof(string);
	return R_P;
}

static int temporaries_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	struct em_temporaries *members = self->members;
	struct neocc_string *string;

	if (action != NEOCC_AC2_TEMPORARIES_POP) {
		SBO_OBJECT_INTERACT2;
	}
	if (!self->ref_count || quantity != sizeof(string))
		return RN_INVALIDARG;
	memcpy(&string, input_stream, sizeof(string));
	if (!members->top || members->top->boundary ||
	    string != &members->top->string)
		return RN_INVALIDARG;
	temporaries_pop(members);
	return R_P;
}

static int temporaries_interact3(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	SBO_OBJECT_INTERACT3;
}

void tog_temporaries(struct object *object)
{
	object->open = temporaries_open;
	object->input = temporaries_input;
	object->output = temporaries_output;
	object->io_put = temporaries_io_put;
	object->interact0 = temporaries_interact0;
	object->interact1 = temporaries_interact1;
	object->interact2 = temporaries_interact2;
	object->interact3 = temporaries_interact3;
	object->close = temporaries_close;
}
